INSERT INTO `email_templates_details` (`id`, `template_id`, `subject`, `template_body`, `notified`, `branch_id`) VALUES
(1, 2, 'Password Reset Request', '<p><strong>Dear {username},</strong></p><p>We received a request to reset the password associated with your account. To proceed, please use the link below to set a new password:</p><p><a rel=\"noopener\"><a href=\"http://{reset_url}\">Reset Your Password</a></a></p><p>If you did not request a password reset, please disregard this message. This link will expire soon, so we recommend completing the reset as soon as possible.</p><p>Thank you,<br>{<span xss=removed>institute_name</span>} Support Team</p>', 1, 9);
